    display: inline-block;
    padding: 6px 14px;
    border-radius: 999px;
    font-weight: 800;
    font-size: 13px;
    color: #fff;
}

/* Smooth transitions */
.card, .bslib-value-box, .accordion {
    transition: box-shadow 0.2s ease;
}
.card:hover {
    box-shadow: 0 2px 12px rgba(0,0,0,0.4);
}

/* Clickable images — zoom cursor */
.zoomable-img {
    cursor: zoom-in;
    transition: opacity 0.15s ease;
}
.zoomable-img:hover {
    opacity: 0.85;
}

/* Lightbox overlay */
.mbp-lightbox {
    display: none;
    position: fixed;
    top: 0; left: 0; width: 100vw; height: 100vh;
    background: rgba(0,0,0,0.92);
    z-index: 99999;
    justify-content: center;
    align-items: center;
}
.mbp-lightbox.active {
    display: flex;
}
.mbp-lightbox img {
    max-width: 92vw;
    max-height: 90vh;
    border-radius: 8px;
    box-shadow: 0 4px 40px rgba(0,0,0,0.8);
}
.mbp-lightbox-close {
    position: absolute;
    top: 18px; right: 24px;
    font-size: 36px;
    color: #fff;
    cursor: pointer;
    font-weight: 700;
    line-height: 1;
    z-index: 100000;
    background: rgba(0,0,0,0.5);
    border-radius: 50%;
    width: 48px; height: 48px;
    display: flex; align-items: center; justify-content: center;
}
.mbp-lightbox-close:hover {
    background: rgba(255,255,255,0.15);
}
</style>

<!-- Lightbox container + JS -->
<div class="mbp-lightbox" id="mbpLightbox" onclick="this.classList.remove('active')">
    <span class="mbp-lightbox-close" onclick="document.getElementById('mbpLightbox').classList.remove('active')">&times;</span>
    <img id="mbpLightboxImg" src="" alt="Zoomed image" onclick="event.stopPropagation()">
</div>
<script>
function mbpZoom(el){
    var lb=document.getElementById('mbpLightbox');
    document.getElementById('mbpLightboxImg').src=el.src;
    lb.classList.add('active');
}
</script>
"""


# ===================================================================
# Image helper (must be defined before UI tree that references it)
# ===================================================================

def _zoomable_img(src: str, alt: str = "", max_width: str = "800px") -> Tag:
    """Return an <img> that opens in a lightbox overlay when clicked."""
    return ui.tags.img(
        src=src,
        alt=alt,
        class_="zoomable-img",
        onclick="mbpZoom(this)",
        style=f"width: 100%; max-width: {max_width}; border-radius: 8px; margin-top: 8px;",
    )


# ===================================================================
# UI Definition
# ===================================================================

# Goal options for the Analyze page
GOAL_OPTIONS = {
