    "10k": "10 km",
    "16k": "16 km (10 miler)",
    "half": "21.1 km (Half Marathon)",
    "32k": "32 km",
    "marathon": "42.2 km (Marathon)",
    "hyrox": "Hyrox",
    "custom_distance": "Custom distance (km)",
    "custom_time": "Custom time (minutes)",
