                ),
                ui.output_text("goal_summary_text"),
            ),
            # Step 2: Upload
            ui.card(
                ui.card_header("Step 2. Upload your .FIT file"),
                ui.input_file("fit_file", "Upload activity file (.FIT or .zip)", accept=[".fit", ".zip"], multiple=False),
                ui.output_ui("upload_status"),
                ui.accordion(
                    ui.accordion_panel(
