                                                    alt="AD with Incline",
                                                ),
                                                ui.tags.div(
                                                    HTML("&#9654;"),
                                                    style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); "
                                                          "font-size: 64px; color: rgba(255,255,255,0.9); text-shadow: 0 2px 8px rgba(0,0,0,0.6);",
                                                ),
                                                href="https://youtu.be/5l9rS6h6P5g",
                                                target="_blank",
