                    ),
                    icon=fa.icon_svg("graduation-cap"),
                ),
                id="edu_accordion",
                open=False,
            ),
            # Manual power (conditional — shown after upload if needed)
            ui.output_ui("manual_power_visibility_wrapper"),
            # Analysis results (Inverted Pyramid: KPIs → Charts → Deep Dive)
            ui.output_ui("analysis_results"),
        ),
    ),
    ui.nav_panel(
        "Compare",
        ui.layout_sidebar(
            compare_sidebar,
            ui.card(
                ui.card_header("Durability Trends — Compare"),
                ui.p(
