# ===================================================================
# Server
# ===================================================================

def server(input: Inputs, output: Outputs, session: Session):
    # ----- Reactive values -----
    parsed_data = reactive.Value(None)  # (meta, df_raw) tuple
    fit_bytes_val = reactive.Value(b"")
    fit_name_val = reactive.Value("")
    history_trigger = reactive.Value(0)  # increment to reload history

    # ----- Helper: read FIT bytes from uploaded file -----
    @reactive.Calc
    def fit_upload_info():
        """Extract FIT bytes from the uploaded file."""
        file_info: list[FileInfo] = input.fit_file()
        req(file_info)
        fi = file_info[0]
        fpath = fi["datapath"]
        fname = fi["name"]

        with open(fpath, "rb") as f:
            raw_data = f.read()

        lower = fname.lower()
        # Normal .fit
        if lower.endswith(".fit"):
            return raw_data, fname
        # FIT header check
        if len(raw_data) >= 12 and raw_data[8:12] == b".FIT":
            return raw_data, fname
        # Zip
        if lower.endswith(".zip"):
            try:
                with zipfile.ZipFile(io.BytesIO(raw_data)) as z:
                    members = [m for m in z.namelist() if m.lower().endswith(".fit")]
                    if members:
                        chosen = sorted(members, key=lambda s: (s.count("/"), len(s), s))[0]
                        return z.read(chosen), chosen
            except Exception:
                pass
            return None, fname
        return None, fname

    @reactive.Calc
    def parsed_fit():
        """Parse FIT file."""
        info = fit_upload_info()
        req(info)
        fbytes, fname = info
        req(fbytes)
        meta, df_raw = parse_fit_bytes(fbytes)
        req(not df_raw.empty)
        return meta, df_raw, fname, fbytes

    @reactive.Calc
    def mode_resolved():
        """Auto-detect activity mode from FIT file metadata."""
        data = parsed_fit()
        req(data)
        meta, df_raw, _, _ = data
        df_base = ensure_elapsed_sec(df_raw)
        return infer_mode(meta, df_base)

    @reactive.Calc
    def df_work_calc():
        """Build working DataFrame with NGP if running."""
        data = parsed_fit()
        req(data)
        meta, df_raw, _, _ = data
        mode = mode_resolved()
        df_base = ensure_elapsed_sec(df_raw)
        if mode == "run":
            df_work = add_ngp_speed(df_base)
            df_work = ensure_elapsed_sec(df_work)
        else:
            df_work = df_base
        return df_work

    # ---- Determine if manual power is needed (independent of analysis) ----
    @reactive.Calc
    def needs_manual_power_check():
        """Check if manual power is needed based on parsed FIT + mode, without running analysis."""
        data = parsed_fit()
        req(data)
        meta, df_raw, fname, fbytes = data
        mode = mode_resolved()
        df_work = df_work_calc()

        pw_raw = pd.to_numeric(df_work["power_w"], errors="coerce") if "power_w" in df_work.columns else None
        has_native_power = bool(pw_raw is not None and pw_raw.notna().any() and float(pw_raw.fillna(0).max()) > 0)
        erg_subtype = infer_erg_subtype(meta) if mode == "erg" else "erg"
        output_col, output_unit, output_used = choose_output_metric(mode=mode, df=df_work, has_native_power=has_native_power)
        return bool((mode != "run") and (output_col == "power_w") and (not has_native_power))

    # ---- Store manual power value persistently ----
    _manual_power_stored = reactive.Value(0.0)

    @reactive.Effect
    def _sync_manual_power():
        """Sync the manual power input to a persistent reactive value."""
        try:
            val = float(input.manual_avg_power_w() or 0)
        except Exception:
            val = 0.0
        _manual_power_stored.set(val)

    @reactive.Calc
    def analysis_result():
        """Run the full analysis pipeline."""
        analysis = _get_analysis()
        data = parsed_fit()
        req(data)
        meta, df_raw, fname, fbytes = data
        mode = mode_resolved()
        df_work = df_work_calc()

        # Total duration
        total_elapsed_sec = float(pd.to_numeric(df_work["elapsed_sec"], errors="coerce").max()) if "elapsed_sec" in df_work.columns else float("nan")
        total_minutes = total_elapsed_sec / 60.0 if np.isfinite(total_elapsed_sec) else float("nan")

        # Output metric
        pw_raw = pd.to_numeric(df_work["power_w"], errors="coerce") if "power_w" in df_work.columns else None
        has_native_power = bool(pw_raw is not None and pw_raw.notna().any() and float(pw_raw.fillna(0).max()) > 0)
        erg_subtype = infer_erg_subtype(meta) if mode == "erg" else "erg"
        output_col, output_unit, output_used = choose_output_metric(mode=mode, df=df_work, has_native_power=has_native_power)

        needs_manual_power = bool((mode != "run") and (output_col == "power_w") and (not has_native_power))

        # Settings
        warmup_min = int(input.warmup_min() or 15)
        end_exclude_min = int(input.end_exclude_min() or 0)
        ftp_w = float(input.ftp_w() or 0)
        stride_thr_pct = float(input.stride_thr_pct() or 1.25)
        min_stride_confirm_sec = int(input.min_stride_confirm_sec() or 3)
        recovery_buffer_sec = int(input.recovery_buffer_sec() or 60)
        stride_mode = str(input.stride_mode() or "Option A — stop analysis at first stride")
        pause_power_w = float(input.pause_power_w() or 5.0)
        pause_speed_kph = float(input.pause_speed_kph() or 0.8)
        pause_speed_mps = pause_speed_kph / 3.6
        max_gap_sec = 10.0

        # Resample to 1Hz
        cols_1hz = ["heart_rate", "power_w", "cadence", "speed_mps", "ngp_speed_mps", "grade"]
        df_full_1hz, gap_break_sec_full = analysis.resample_records_to_1hz(df_work, cols_1hz, max_gap_sec=max_gap_sec)
        if not df_full_1hz.empty:
            df_full_1hz = df_full_1hz.sort_index()
            t0 = df_work.index[0]
            df_full_1hz["elapsed_sec"] = (df_full_1hz.index - t0).total_seconds()

        # Prepare clean segment
        clean = analysis.prepare_clean_segment_1hz(
            df_work,
            warmup_sec=warmup_min * 60,
            end_exclude_sec=end_exclude_min * 60,
            max_gap_sec=max_gap_sec,
            cadence_required_ratio=0.60,
            ftp_w=ftp_w,
            stride_thr_pct=stride_thr_pct,
            min_stride_confirm_sec=min_stride_confirm_sec,
            recovery_buffer_sec=recovery_buffer_sec,
            stride_mode=stride_mode,
            pause_fallback_power_w=pause_power_w,
            pause_fallback_speed_mps=pause_speed_mps,
            df_full_1hz=df_full_1hz,
            gap_break_sec_full=gap_break_sec_full,
        )

        if clean.df_used_1hz.empty:
            return {"error": "Not enough valid steady data after exclusions.", "notes": clean.notes}

        # Manual power injection if needed
        manual_power = None
        if needs_manual_power:
            manual_power = _manual_power_stored()
            if manual_power and manual_power > 0:
                from dataclasses import replace as dc_replace
                df_used_manual = clean.df_used_1hz.copy()
                df_used_manual["power_w"] = float(manual_power)
                notes = list(clean.notes) if isinstance(clean.notes, list) else []
                notes.append(f"Manual average power used: {manual_power:.0f} W")
                clean = dc_replace(clean, df_used_1hz=df_used_manual, notes=notes)
            elif needs_manual_power:
                return {"error": "Manual power required but not provided.", "needs_manual_power": True}

        seconds_analyzed = len(clean.df_used_1hz)
        minutes_analyzed = seconds_analyzed / 60.0

        # Terrain
        used_start_sec = clean.used_start_sec or 0.0
        es_max = pd.to_numeric(df_work["elapsed_sec"], errors="coerce") if "elapsed_sec" in df_work.columns else pd.Series(dtype=float)
        used_end_sec = clean.used_end_sec if clean.used_end_sec else (float(es_max.max()) if es_max.notna().any() else 0)

        df_used_records = df_work
        if clean.used_intervals_sec:
            es_all = pd.to_numeric(df_work["elapsed_sec"], errors="coerce") if "elapsed_sec" in df_work.columns else pd.Series(dtype=float)
            mask = np.zeros(len(df_work), dtype=bool)
            for a, b in clean.used_intervals_sec:
                if a is not None and b is not None:
                    mask |= (es_all >= float(a)) & (es_all <= float(b))
            df_used_records = df_work.loc[mask].copy()

        terrain_info = compute_terrain(df_used_records, max_gap_sec=max_gap_sec, mode=mode)
        terrain = terrain_info.terrain
        decoupling_zone = terrain_decoupling_zone(float(terrain_info.gain_per_km), terrain=terrain)

        # Terrain-aware output
        if mode == "run":
            run_power_ok = bool(
                has_native_power
                and "power_w" in clean.df_used_1hz.columns
                and pd.to_numeric(clean.df_used_1hz["power_w"], errors="coerce").notna().any()
            )
            if run_power_ok and terrain in ("Rolling", "Hilly", "Mountainous"):
                output_col = "power_w"
                output_unit = "W"
                output_used = "Running Power"

        # Decoupling
        res = analysis.compute_decoupling_1hz(clean.df_used_1hz, output_col=output_col)
        if res is None:
            return {"error": "Not enough valid data for decoupling calculation."}

        ef, avg_out, avg_hr = analysis.compute_overall_ef_1hz(clean.df_used_1hz, output_col=output_col, decoupling_res=res)

        # Terrain alternatives
        beats_per_km = cardiac_cost_first_half = cardiac_cost_second_half = cardiac_cost_rise_pct = float("nan")
        segment_ef_drop_pct = float("nan")
        segment_ef_note = ""
        energy_kj = power_decay_pct = float("nan")
        power_decay_note = ""

        if mode == "run":
            cc = compute_cardiac_cost_metrics_1hz(clean.df_used_1hz)
            try:
                beats_per_km = float(cc.get("beats_per_km", float("nan")))
                cardiac_cost_first_half = float(cc.get("beats_per_km_first_half", float("nan")))
                cardiac_cost_second_half = float(cc.get("beats_per_km_second_half", float("nan")))
                cardiac_cost_rise_pct = float(cc.get("rise_pct", float("nan")))
            except Exception:
                pass

            if terrain == "Hilly":
                seg = compute_segment_ef_stability(clean.df_used_1hz, window_min=20)
                try:
                    segment_ef_drop_pct = float(seg.get("drift_pct", float("nan")))
                    segment_ef_note = str(seg.get("note", ""))
                except Exception:
                    pass

            if "power_w" in clean.df_used_1hz.columns:
                pd_result = compute_power_decay_after_kj(clean.df_used_1hz, kj_threshold=2000.0, window_min=20)
                try:
                    energy_kj = float(pd_result.get("energy_kj", float("nan")))
                    power_decay_pct = float(pd_result.get("decay_pct", float("nan")))
                    power_decay_note = str(pd_result.get("note", ""))
                except Exception:
                    pass

        # Thresholds and status
        low_thr, high_thr = thresholds_for_session(mode=mode, terrain=terrain, minutes_analyzed=minutes_analyzed, erg_subtype=erg_subtype)
        status = analysis.classify_decoupling(float(res.decoupling_pct), float(low_thr), float(high_thr), mode=mode, terrain=terrain)

        # Terrain override for hilly/mountainous runs
        if mode == "run" and terrain == "Hilly" and np.isfinite(segment_ef_drop_pct):
            d = float(segment_ef_drop_pct)
            if d <= 2.0:
                status = f"Elite - increase pace/distance (segment EF drift {abs(d):.1f}%)"
            elif d <= 5.0:
                status = f"Adapting - maintain pace/distance (segment EF drift {abs(d):.1f}%)"
            else:
                status = f"Needs Lessening of pace/distance (segment EF drift {abs(d):.1f}%)"

        if mode == "run" and terrain == "Mountainous" and np.isfinite(cardiac_cost_rise_pct):
            r = float(cardiac_cost_rise_pct)
            r_eff = max(r, 0.0)
            if r_eff <= 5.0:
                status = f"Elite - increase pace/distance (cardiac cost drift {abs(r):.1f}%)"
            elif r_eff <= 10.0:
                status = f"Adapting - maintain pace/distance (cardiac cost drift {abs(r):.1f}%)"
            else:
                status = f"Needs Lessening of pace/distance (cardiac cost drift +{r_eff:.1f}%)"

        # Averages
        avg_speed_kph = float("nan")
        if "speed_mps" in clean.df_used_1hz.columns:
            avg_speed_kph = float(pd.to_numeric(clean.df_used_1hz["speed_mps"], errors="coerce").mean()) * 3.6

        avg_power_w = float("nan")
        if "power_w" in clean.df_used_1hz.columns:
            avg_power_w = float(pd.to_numeric(clean.df_used_1hz["power_w"], errors="coerce").mean())

        avg_cadence = float("nan")
        if "cadence" in clean.df_used_1hz.columns:
            avg_cadence = float(pd.to_numeric(clean.df_used_1hz["cadence"], errors="coerce").mean())

        # Goal computation
        goal_choice = input.goal_choice()
        event_goal_min = 60.0
        speed_for_goal = avg_speed_kph if np.isfinite(avg_speed_kph) else float("nan")

        if goal_choice == "custom_time":
            try:
                event_goal_min = float(np.clip(input.goal_custom_time_min() or 60, 10, 2000))
            except Exception:
                event_goal_min = 60.0
        elif goal_choice == "custom_distance":
            try:
                dist = float(input.goal_custom_distance_km() or 10)
            except Exception:
                dist = 10.0
            if np.isfinite(speed_for_goal) and speed_for_goal > 0:
                event_goal_min = float(np.clip((dist / speed_for_goal) * 60.0, 10, 2000))
        elif goal_choice in GOAL_DISTANCES_KM:
            dist = GOAL_DISTANCES_KM[goal_choice]
            if np.isfinite(speed_for_goal) and speed_for_goal > 0:
                event_goal_min = float(np.clip((dist / speed_for_goal) * 60.0, 10, 2000))
        elif goal_choice == "hyrox":
            event_goal_min = 90.0

        # Drift driver
        driver_label, hr_share, out_share = analysis.drift_driver_breakdown(
            hr1=res.hr1, hr2=res.hr2, out1=res.out1, out2=res.out2,
        )

        # Durability detection
        drift_sec, drift_elapsed_sec, drift_conf = analysis.detect_point_of_no_return_details_1hz(
            clean.df_used_1hz,
            hr_col="heart_rate",
            output_col=output_col,
        )

        # Recommendation
        try:
            rec_text = analysis.recommendation_text(
                mode=mode, dec=res.decoupling_pct, low_thr=low_thr, high_thr=high_thr,
                event_goal_min=event_goal_min, total_min=total_minutes,
                avg_out=avg_out, avg_hr=avg_hr, avg_speed_kph=avg_speed_kph,
                output_unit=output_unit, output_used=output_used, erg_subtype=erg_subtype,
                warmup_min=warmup_min, end_exclude_min=end_exclude_min,
                sweat_rate_lph=float(input.sweat_rate_lph() or 0),
            )
        except Exception as _rec_err:
            import traceback as _tb
            print(f"[MBP] recommendation_text error: {_rec_err}\n{''.join(_tb.format_exception(type(_rec_err), _rec_err, _rec_err.__traceback__))}")
            rec_text = ""

        # Weather
        weather = get_activity_weather_summary(meta, df_raw)
        temp_min, temp_max = extract_temp_bounds_from_weather_summary(weather)

        # Garmin name
        garmin_name = (meta.get("athlete_name") or "").strip() or "Athlete"

        # Pre-compute downsampled plot data (chart is built separately for fast display toggling)
        df_plot = downsample_for_plot(clean.df_used_1hz, max_points=800)

        return {
            "df_plot": df_plot,
            "meta": meta,
            "df_raw": df_raw,
            "fname": fname,
            "mode": mode,
            "terrain": terrain,
            "terrain_info": terrain_info,
            "decoupling_zone": decoupling_zone,
            "output_col": output_col,
            "output_unit": output_unit,
            "output_used": output_used,
            "erg_subtype": erg_subtype,
            "total_minutes": total_minutes,
            "minutes_analyzed": minutes_analyzed,
            "seconds_analyzed": seconds_analyzed,
            "res": res,
            "ef": ef,
            "avg_out": avg_out,
            "avg_hr": avg_hr,
            "avg_speed_kph": avg_speed_kph,
            "avg_power_w": avg_power_w,
            "avg_cadence": avg_cadence,
            "low_thr": low_thr,
            "high_thr": high_thr,
            "status": status,
            "driver_label": driver_label,
            "hr_share": hr_share,
            "out_share": out_share,
            "drift_sec": drift_sec,
            "drift_elapsed_sec": drift_elapsed_sec,
            "drift_conf": drift_conf,
            "rec_text": rec_text,
            "weather": weather,
            "garmin_name": garmin_name,
            "event_goal_min": event_goal_min,
            "beats_per_km": beats_per_km,
            "cardiac_cost_rise_pct": cardiac_cost_rise_pct,
            "segment_ef_drop_pct": segment_ef_drop_pct,
            "power_decay_pct": power_decay_pct,
            "power_decay_note": power_decay_note,
            "energy_kj": energy_kj,
            "needs_manual_power": needs_manual_power,
            "clean": clean,
            "warmup_min": warmup_min,
            "end_exclude_min": end_exclude_min,
            "has_native_power": has_native_power,
            "temp_min": temp_min,
            "temp_max": temp_max,
        }

    # ---- Chart output (only the chart — sidebar controls are in analysis_results) ----
    @output
    @render.ui
    def analysis_chart_output():
        """Render just the Plotly chart HTML.

        The switch inputs (show_hr, show_output, show_cadence, smoothing)
        live in the parent layout_sidebar created by analysis_results(),
        so they persist across re-renders. This output only re-renders
        when the switches or analysis_result() change.
        """
        result = analysis_result()
        req(result)
        if "error" in result:
            return ui.div()

        go = _get_plotly_go()
        df_plot = result["df_plot"]
        output_col = result["output_col"]
        output_used = result["output_used"]
        output_unit = result["output_unit"]

        smooth_map = {"raw": 1, "3s": 3, "10s": 10, "30s": 30}
        smooth_win = smooth_map.get(input.smoothing(), 1)

        fig = go.Figure()
        es = pd.to_numeric(df_plot["elapsed_sec"], errors="coerce") if "elapsed_sec" in df_plot.columns else pd.Series(dtype=float)
        x_vals = (pd.Timestamp("1970-01-01") + pd.to_timedelta(es, unit="s")) if es.notna().any() else pd.RangeIndex(len(df_plot))

        if input.show_hr() and "heart_rate" in df_plot.columns:
            hr_data = pd.to_numeric(df_plot["heart_rate"], errors="coerce")
            if smooth_win > 1:
                hr_data = hr_data.rolling(smooth_win, min_periods=1, center=True).mean()
            fig.add_trace(go.Scatter(
                x=x_vals, y=hr_data, name="Heart Rate",
                mode="lines", line=dict(color=COLOR_HR, width=1.5), yaxis="y",
            ))

        if input.show_output() and output_col in df_plot.columns:
            out_data = pd.to_numeric(df_plot[output_col], errors="coerce")
            if smooth_win > 1:
                out_data = out_data.rolling(smooth_win, min_periods=1, center=True).mean()
            out_color = COLOR_POWER if "power" in output_col.lower() else COLOR_SPEED
            fig.add_trace(go.Scatter(
                x=x_vals, y=out_data, name=output_used,
                mode="lines", line=dict(color=out_color, width=1.5), yaxis="y2",
            ))

        if input.show_cadence() and "cadence" in df_plot.columns:
            cad_data = pd.to_numeric(df_plot["cadence"], errors="coerce")
            if smooth_win > 1:
                cad_data = cad_data.rolling(smooth_win, min_periods=1, center=True).mean()
            fig.add_trace(go.Scatter(
                x=x_vals, y=cad_data, name="Cadence",
                mode="lines", line=dict(color=COLOR_CADENCE, width=1), yaxis="y", opacity=0.5,
            ))

        fig.update_layout(
            height=420,
            margin=dict(l=10, r=10, t=30, b=10),
            xaxis_title="Elapsed Time",
            yaxis=dict(title="Heart Rate (bpm)", side="left", color=COLOR_HR),
            yaxis2=dict(title=f"{output_used} ({output_unit})", side="right", overlaying="y",
                        color=COLOR_POWER if "power" in output_col.lower() else COLOR_SPEED),
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(16,16,16,0.8)",
            legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0.5)"),
            xaxis=dict(tickformat="%H:%M:%S", gridcolor="rgba(255,255,255,0.05)"),
            font=dict(family="Roboto Mono, JetBrains Mono, monospace", color="rgba(255,255,255,0.85)"),
        )

        try:
            chart_html = fig.to_html(full_html=False, include_plotlyjs=False, config={"responsive": True})
        except Exception as e:
            chart_html = f"<p>Chart rendering error: {e}</p>"

        return ui.HTML(chart_html)

