    @output
    @render.ui
    def analysis_results():
        """Render analysis results using Inverted Pyramid layout (Section 2.1)."""
        result = analysis_result()
        req(result)
        if "error" in result:
            notes = result.get("notes", [])
            note_html = ""
            if notes:
                note_html = ui.tags.ul(*[ui.tags.li(n) for n in notes])
            return ui.div(
                ui.div(
                    ui.tags.strong("⚠ "), result["error"],
                    style=f"color: #fff; background: {COLOR_NEEDS_WORK}; padding: 12px 16px; border-radius: 8px; font-weight: 700; margin-bottom: 12px;",
                ),
                note_html,
            )

        # Unpack results
        mode = result["mode"]
        terrain = result["terrain"]
        terrain_info = result["terrain_info"]
        res = result["res"]
        status = result["status"]
        ef = result["ef"]
        avg_hr = result["avg_hr"]
        avg_out = result["avg_out"]
        avg_speed_kph = result["avg_speed_kph"]
        avg_power_w = result["avg_power_w"]
        avg_cadence = result["avg_cadence"]
        low_thr = result["low_thr"]
        high_thr = result["high_thr"]
        output_used = result["output_used"]
        output_unit = result["output_unit"]
        minutes_analyzed = result["minutes_analyzed"]
        total_minutes = result["total_minutes"]
        garmin_name = result["garmin_name"]
        driver_label = result["driver_label"]
        drift_sec = result["drift_sec"]
        drift_conf = result["drift_conf"]
        rec_text = result["rec_text"]
        weather = result["weather"]
        decoupling_zone = result["decoupling_zone"]

        dec_pct = res.decoupling_pct
        color = _rag_color_for(status)

        # Build metrics
        km_str = f"{terrain_info.distance_km:.2f} km" if np.isfinite(terrain_info.distance_km) else "—"
        gain_str = f"{terrain_info.elev_gain_m:.0f} m" if np.isfinite(terrain_info.elev_gain_m) else "—"
        pace_str = pace_str_from_speed_mps(avg_speed_kph / 3.6) if np.isfinite(avg_speed_kph) and avg_speed_kph > 0 else "—"

        drift_str = "—"
        if drift_sec is not None and drift_conf != "low":
            drift_str = format_duration(drift_sec)
            drift_str += f" ({drift_conf})"

        # Decoupling badge
        thr_ok = np.isfinite(low_thr) and np.isfinite(high_thr)
        thr_desc = f"Thresholds: <{_fmt_thr_pct(low_thr)}% / {_fmt_thr_pct(low_thr)}-{_fmt_thr_pct(high_thr)}% / >{_fmt_thr_pct(high_thr)}%" if thr_ok else ""

        # ============================================================
        # INVERTED PYRAMID LAYOUT (Section 2.1)
        # ============================================================
        return ui.TagList(
            # ---- TIER 1: THE GLANCE (5-second rule) ----
            # Greeting + Activity context
            ui.card(
                ui.div(
                    ui.h3(f"Hello, {garmin_name}!", style=f"color: {COLOR_ELITE}; margin: 0;"),
                    ui.p(f"Terrain: {terrain} ({decoupling_zone}) — {km_str} — Gain: {gain_str}",
                         style="margin: 4px 0 0 0; opacity: 0.8;"),
                    style="background: rgba(46,93,75,0.92); border-radius: 12px; padding: 16px;",
                ),
            ),
            # Warning for short files
            _short_file_warning(mode, total_minutes),
            # HERO Decoupling badge — the primary KPI (Section 10.1)
            ui.card(
                ui.card_header(f"Aerobic Decoupling % ({output_used})"),
                ui.div(
                    ui.div(
                        ui.span(f"{dec_pct:.1f}%", style=f"font-size: 48px; font-weight: 850; color: {color}; font-family: 'Roboto Mono', monospace;"),
                        style="margin-right: 16px;",
                    ),
                    ui.div(
                        ui.span(status, class_="status-badge", style=f"background: {color};"),
                    ),
                    style="display: flex; align-items: center; flex-wrap: wrap; gap: 12px;",
                ),
                ui.p(HTML(thr_desc), style="font-size: 13px; opacity: 0.7; margin-top: 8px;") if thr_ok else None,
            ),
            # ---- TIER 2: PROGRESSIVE DISCLOSURE (Section 2.2) ----
            ui.accordion(
                # Recommendation
                ui.accordion_panel(
                    "Next Session Recommendation",
                    ui.div(HTML(_md_to_html(rec_text))) if rec_text else ui.p("No recommendation available.", style="opacity: 0.6;"),
                    icon=fa.icon_svg("clipboard-list"),
                ),
                # Heart Rate & Output Timeline with inline sidebar controls
                ui.accordion_panel(
                    "Heart Rate & Output Timeline",
                    ui.layout_sidebar(
                        ui.sidebar(
                            ui.input_switch("show_hr", "Show Heart Rate", value=True),
                            ui.input_switch("show_output", "Show Output Metric", value=True),
                            ui.input_switch("show_cadence", "Show Cadence", value=False),
                            ui.input_select(
                                "smoothing", "Smoothing",
                                choices={"raw": "Raw", "3s": "3s Average", "10s": "10s Average", "30s": "30s Average"},
                                selected="30s",
                            ),
                            width=200,
                            open="desktop",
                        ),
                        ui.output_ui("analysis_chart_output"),
                    ),
                    icon=fa.icon_svg("chart-area"),
                ),
                # Metrics — key session KPIs
                ui.accordion_panel(
                    "Metrics",
                    ui.layout_columns(
                        ui.value_box("Efficiency Factor", f"{ef:.4f}" if np.isfinite(ef) else "—",
                                     showcase=fa.icon_svg("chart-line"), theme="primary"),
                        ui.value_box("Avg HR", f"{avg_hr:.0f} bpm" if np.isfinite(avg_hr) else "—",
                                     showcase=fa.icon_svg("heart-pulse"), theme="danger"),
                        ui.value_box(f"Avg {output_used}", f"{avg_out:.1f} {output_unit}" if np.isfinite(avg_out) else "—",
                                     showcase=fa.icon_svg("bolt"), theme="info"),
                        ui.value_box("Avg Pace" if mode == "run" else "Avg Speed",
                                     pace_str if mode == "run" else (f"{avg_speed_kph:.1f} km/h" if np.isfinite(avg_speed_kph) else "—"),
                                     showcase=fa.icon_svg("gauge-high"), theme="success"),
                        col_widths=[3, 3, 3, 3],
                    ),
                    ui.layout_columns(
                        ui.value_box("Minutes Analyzed", f"{minutes_analyzed:.1f}" if np.isfinite(minutes_analyzed) else "—",
