            hist = hist[hist["start_time_iso"].astype(str) != PROFILE_META_START_TIME_ISO].copy()
        else:
            hist = hist.copy()
        if hist.empty:
            return hist

        # Activity type filter
        filter_types = input.compare_filter_type()
        if filter_types:
            hist = hist[hist["mode"].astype(str).str.strip().str.lower().isin(filter_types)]

        # Distance filter
        target = float(input.compare_target_dist_km() or 0)
        tol = float(input.compare_dist_tol_km() or 5)
        if target > 0 and "distance_km" in hist.columns:
            dk = pd.to_numeric(hist["distance_km"], errors="coerce")
            hist = hist[(dk >= target - tol) & (dk <= target + tol)]

        # Date filter
        try:
            dr = input.compare_date_range()
            if dr and len(dr) == 2:
                hist["_dt"] = pd.to_datetime(hist["date"], errors="coerce")
                hist = hist[(hist["_dt"] >= pd.Timestamp(dr[0])) & (hist["_dt"] <= pd.Timestamp(dr[1]))]
                hist = hist.drop(columns=["_dt"], errors="ignore")
        except Exception:
            pass

